import pytest


def settings(keys: list[str], values: list[str]) -> list[str]:
    """Overlay the given settings on the defaults mode=fast and level=3.

    `keys[i]` is set to `values[i]`. The result holds the final values in this
    order: the value of "mode", the value of "level", then the values of any
    other keys in order of first appearance in `keys`. If a key repeats, the
    last value given for it wins, and its position stays at its first
    appearance.

    Raises ValueError if `keys` and `values` differ in length.
    """
    if len(keys) != len(values):
        raise ValueError("keys and values differ in length")
    merged: dict[str, str] = {"mode": "fast", "level": "3"}
    for k, v in zip(keys, values, strict=True):
        merged[k] = v
    return list(merged.values())


def test_defaults_when_empty() -> None:
    assert settings([], []) == ["fast", "3"]


def test_override_mode_only() -> None:
    assert settings(["mode"], ["slow"]) == ["slow", "3"]


def test_override_level_only() -> None:
    assert settings(["level"], ["5"]) == ["fast", "5"]


def test_override_both_in_reverse_order() -> None:
    assert settings(["level", "mode"], ["9", "slow"]) == ["slow", "9"]


def test_extra_keys_follow_in_given_order() -> None:
    assert settings(["x", "mode", "y"], ["1", "slow", "2"]) == ["slow", "3", "1", "2"]


def test_extra_keys_only() -> None:
    assert settings(["b", "a"], ["2", "1"]) == ["fast", "3", "2", "1"]


def test_duplicate_extra_key_last_wins_first_position() -> None:
    assert settings(["x", "y", "x"], ["1", "2", "3"]) == ["fast", "3", "3", "2"]


def test_duplicate_default_key_last_wins() -> None:
    assert settings(["mode", "mode"], ["a", "b"]) == ["b", "3"]


def test_values_are_strings_unchanged() -> None:
    assert settings(["level", "k"], ["", " v "]) == ["fast", "", " v "]


def test_length_mismatch_raises() -> None:
    with pytest.raises(ValueError):
        settings(["a", "b"], ["1"])
    with pytest.raises(ValueError):
        settings([], ["1"])


def test_inputs_not_mutated() -> None:
    keys = ["x", "mode"]
    values = ["1", "slow"]
    settings(keys, values)
    assert keys == ["x", "mode"]
    assert values == ["1", "slow"]
